//! Admit complete path and byte changes before effects, including active and staged bytes.
use super::*;
const MAX_NAMES: usize = 512 * 1024;

/// Physical kind and current conservative charge, indexed by the Windows case-folded name.
struct Member {
    name: String,
    directory: bool,
    bytes: u64,
}
/// Bounded original grant inventory; failed effects retain conservative names and byte charges.
pub(super) struct Index {
    members: BTreeMap<String, Member>,
    names: usize,
    bytes: u64,
    maximum: u64,
    root: PathBuf,
}
impl Index {
    /// Start bounded accounting for one actual canonical generated grant.
    pub(super) fn new(maximum: u64, root: PathBuf) -> io::Result<Self> {
        if root.to_str().is_none() {
            return Err(invalid("Cache root is not Unicode"));
        }
        Ok(Self { members: BTreeMap::new(), names: 0, bytes: 0, maximum, root })
    }
    /// Validate complete ancestor/type/alias/name/byte admission before modifying the index.
    pub(super) fn admit(&mut self, name: &str, directory: bool, bytes: u64) -> io::Result<()> {
        files::relative(name)
            .map_err(|cause| io::Error::new(io::ErrorKind::InvalidInput, cause))?;
        if name.contains('\\')
            || name.split('/').count() > MAX_DEPTH
            || self.root.join(name).to_string_lossy().len() > 4096
        {
            return Err(invalid("Generated path exceeds its supported shape"));
        }
        let mut proposed = Vec::new();
        let mut additional = 0;
        let mut path = String::new();
        let mut components = name.split('/').peekable();
        while let Some(component) = components.next() {
            if !path.is_empty() {
                path.push('/');
            }
            path.push_str(component);
            let directory = components.peek().is_some() || directory;
            let key = path.to_lowercase();
            match self.members.get(&key) {
                Some(existing) if existing.name != path || existing.directory != directory => {
                    return Err(invalid("Generated path aliases an existing object"));
                }
                Some(_) => {}
                None => {
                    additional += path.len() + 8;
                    if self.members.len() + proposed.len() >= MAX_FILES
                        || self.names + additional > MAX_NAMES
                    {
                        return Err(invalid("Generated inventory capacity exceeded"));
                    }
                    proposed.push((key, path.clone(), directory));
                }
            }
        }
        let key = name.to_lowercase();
        let old = self.members.get(&key).map_or(0, |member| member.bytes);
        let next = self
            .bytes
            .checked_sub(old)
            .and_then(|value| value.checked_add(bytes))
            .filter(|value| *value <= self.maximum)
            .ok_or_else(|| {
                io::Error::new(io::ErrorKind::StorageFull, "Generated cache byte grant exhausted")
            })?;
        for (key, name, directory) in proposed {
            self.members.insert(key, Member { name, directory, bytes: 0 });
        }
        self.names += additional;
        self.bytes = next;
        let member =
            self.members.get_mut(&key).ok_or_else(|| invalid("Generated admission missing"))?;
        member.bytes = bytes;
        Ok(())
    }
    /// Return an already admitted exact filename, never a case alias or directory.
    pub(super) fn charge(&self, name: &str) -> io::Result<Option<u64>> {
        match self.members.get(&name.to_lowercase()) {
            Some(member) if member.name != name || member.directory => {
                Err(invalid("Generated file identity changed"))
            }
            Some(member) => Ok(Some(member.bytes)),
            None => Ok(None),
        }
    }
    /// Remove accounting only after the exact native file has actually retired or published away.
    pub(super) fn removed(&mut self, name: &str) -> io::Result<()> {
        self.charge(name)?;
        if let Some(member) = self.members.remove(&name.to_lowercase()) {
            self.names -= member.name.len() + 8;
            self.bytes -= member.bytes;
        }
        Ok(())
    }
    /// Rechecking must not legitimize external files, changed types, aliases or excess bytes.
    pub(super) fn validate(&self, physical: &tree::Inventory) -> io::Result<()> {
        if physical.bytes > self.bytes {
            return Err(invalid("Generated bytes changed outside their owner"));
        }
        for name in &physical.files {
            if self.charge(name)?.is_none() {
                return Err(invalid("Unadmitted generated file"));
            }
        }
        for name in &physical.directories {
            if !self
                .members
                .get(&name.to_lowercase())
                .is_some_and(|member| member.name == *name && member.directory)
            {
                return Err(invalid("Unadmitted generated directory"));
            }
        }
        Ok(())
    }
}
